module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum sum-of-products:
    //   c & d          covers minterms 7 and 15, using don't-cares 3 and 11
    //   ~a & ~b & c    covers minterm 2, using don't-care 3
    assign out_sop = (~a & ~b & c) | (c & d);

    // Minimum product-of-sums:
    //   c              covers all zeros with c = 0
    //   (~b | d)       covers zeros with b = 1 and d = 0
    //   (~a | b)       covers zeros with a = 1 and b = 0
    assign out_pos = c & (~b | d) & (~a | b);

endmodule
```

Because inputs 3, 8, 11, and 12 are don't-cares, another equally minimum POS expression is also valid:

```verilog
assign out_pos = c & (~b | d) & (~a | d);
```
